VALUES(<PRODUCT_ID_VALUE>, 300, 5100, '{"DB_TYPE": "4", "HEADING": [[{"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "_$dateHeading$_", "ROWSPAN": "2"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Call Received", "ROWSPAN": "2"}, {"ALIGN": "CENTER", "COLSPAN": "3", "DISPLAY": "Answered", "ROWSPAN": "1"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Call Rejected", "ROWSPAN": "2"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Duration[In sec]", "ROWSPAN": "2"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Average", "ROWSPAN": "2"}], [{"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Total Answered"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Total Completed"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Total Disconnected"}]], "REPORT_ID": "500", "BACK_BUTTON": "loadBackPageWithDate(1,'''''''')", "DATE_FILTER": "H,M,Y", "QUERY_INPUT": {"H": "SELECT TO_CHAR(GEN_TIME, ''HH24'') AS C1, COALESCE(SUM(CASE WHEN EVR_CAUSE = 1 THEN COUNT ELSE 0 END), 0) AS C2, COALESCE(SUM(CASE WHEN EVR_CAUSE = 3 THEN COUNT ELSE 0 END), 0) AS C3, COALESCE(SUM(CASE WHEN EVR_CAUSE = 13 THEN COUNT ELSE 0 END), 0) AS C4, COALESCE(SUM(CASE WHEN EVR_CAUSE = 4 THEN COUNT ELSE 0 END), 0) AS C5, COALESCE(SUM(CASE WHEN EVR_CAUSE = 5 THEN COUNT ELSE 0 END), 0) AS C6, COALESCE(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN DURATION ELSE 0 END), 0)::BIGINT AS C7, CASE WHEN COALESCE(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN COUNT ELSE 0 END), 0) = 0 THEN ''0.00'' ELSE TO_CHAR(ROUND(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN DURATION ELSE 0 END)::NUMERIC / NULLIF(SUM(CASE WHEN EVR_CAUSE = 3 THEN COUNT ELSE 0 END), 0), 2), ''FM999999990.00'') END AS C8 FROM ivrschema.IVR_MIS_CUMULATIVE WHERE GEN_TIME BETWEEN TO_TIMESTAMP(''_$fromDate$_'', ''YYYY-MM-DD HH24:MI:SS'') AND TO_TIMESTAMP(''_$toDate$_'', ''YYYY-MM-DD HH24:MI:SS'') AND (''_$ShortCodeName$_'' = ''-1'' OR SHORT_CODE = TO_NUMBER(''_$ShortCodeName$_'')) GROUP BY TO_CHAR(GEN_TIME, ''HH24'') ORDER BY TO_CHAR(GEN_TIME, ''HH24'')", "M": "SELECT TO_CHAR(GEN_TIME, ''YYYY-MM-DD'') AS C1, COALESCE(SUM(CASE WHEN EVR_CAUSE = 1 THEN COUNT ELSE 0 END), 0) AS C2, COALESCE(SUM(CASE WHEN EVR_CAUSE = 3 THEN COUNT ELSE 0 END), 0) AS C3, COALESCE(SUM(CASE WHEN EVR_CAUSE = 13 THEN COUNT ELSE 0 END), 0) AS C4, COALESCE(SUM(CASE WHEN EVR_CAUSE = 4 THEN COUNT ELSE 0 END), 0) AS C5, COALESCE(SUM(CASE WHEN EVR_CAUSE = 5 THEN COUNT ELSE 0 END), 0) AS C6, COALESCE(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN DURATION ELSE 0 END), 0)::BIGINT AS C7, CASE WHEN COALESCE(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN COUNT ELSE 0 END), 0) = 0 THEN ''0.00'' ELSE TO_CHAR(ROUND(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN DURATION ELSE 0 END)::NUMERIC / NULLIF(SUM(CASE WHEN EVR_CAUSE = 3 THEN COUNT ELSE 0 END), 0), 2), ''FM999999990.00'') END AS C8 FROM ivrschema.IVR_MIS_CUMULATIVE WHERE GEN_TIME BETWEEN TO_TIMESTAMP(''_$fromDate$_'', ''YYYY-MM-DD HH24:MI:SS'') AND TO_TIMESTAMP(''_$toDate$_'', ''YYYY-MM-DD HH24:MI:SS'') AND (''_$ShortCodeName$_'' = ''-1'' OR SHORT_CODE = TO_NUMBER(''_$ShortCodeName$_'')) GROUP BY TO_CHAR(GEN_TIME, ''YYYY-MM-DD'') ORDER BY TO_CHAR(GEN_TIME, ''YYYY-MM-DD'')", "Y": "SELECT TO_CHAR(GEN_TIME, ''Month'') AS C1, COALESCE(SUM(CASE WHEN EVR_CAUSE = 1 THEN COUNT ELSE 0 END), 0) AS C2, COALESCE(SUM(CASE WHEN EVR_CAUSE = 3 THEN COUNT ELSE 0 END), 0) AS C3, COALESCE(SUM(CASE WHEN EVR_CAUSE = 13 THEN COUNT ELSE 0 END), 0) AS C4, COALESCE(SUM(CASE WHEN EVR_CAUSE = 4 THEN COUNT ELSE 0 END), 0) AS C5, COALESCE(SUM(CASE WHEN EVR_CAUSE = 5 THEN COUNT ELSE 0 END), 0) AS C6, COALESCE(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN DURATION ELSE 0 END), 0)::BIGINT AS C7, CASE WHEN COALESCE(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN COUNT ELSE 0 END), 0) = 0 THEN ''0.00'' ELSE TO_CHAR(ROUND(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN DURATION ELSE 0 END)::NUMERIC / NULLIF(SUM(CASE WHEN EVR_CAUSE = 3 THEN COUNT ELSE 0 END), 0), 2), ''FM999999990.00'') END AS C8 FROM ivrschema.IVR_MIS_CUMULATIVE WHERE GEN_TIME BETWEEN TO_TIMESTAMP(''_$fromDate$_'', ''YYYY-MM-DD HH24:MI:SS'') AND TO_TIMESTAMP(''_$toDate$_'', ''YYYY-MM-DD HH24:MI:SS'') AND (''_$ShortCodeName$_'' = ''-1'' OR SHORT_CODE = TO_NUMBER(''_$ShortCodeName$_'')) GROUP BY TO_CHAR(GEN_TIME, ''Month''), TO_CHAR(GEN_TIME, ''MM'') ORDER BY TO_CHAR(GEN_TIME, ''MM'')"}, "REPORT_NAME": "Short Code", "OTHER_FILTER": [{"TYPE": "S", "DISPLAY": "Short Code", "FILTER_QUERY": {"QUERY": "SELECT DISTINCT ICU.SHORT_CODE AS C1, ISC.SHORT_CODE AS C2 FROM ivrschema.IVR_MIS_CUMULATIVE ICU JOIN IVR_MIS_CUMULATIVE ISC ON TRIM(ICU.SHORT_CODE) = ISC.SHORT_CODE", "DATA_ID": "C1", "DATA_LABEL": "C2", "QUERY_PARAM_VALUE": "C1"}, "QUERY_PARAM_NAME": "ShortCodeName"}], "PRODUCT_NAME": "IVR", "ROW_TEMPLATE": [{"LINK": "<dateLinkFunctionIfReq>", "DISPLAY": "C1"}, {"DISPLAY": "C2"}, {"DISPLAY": "C3"}, {"DISPLAY": "C4"}, {"DISPLAY": "C5"}, {"DISPLAY": "C6"}, {"DISPLAY": "C7"}, {"DISPLAY": "C8"}], "REPORT_HEADING": "Short Code"}'::jsonb);

